    const macroDoc = await fromUuid(UUID);
    if (!macroDoc) {
        ui.notifications.error("Failed to load compendium macro.");
        return;
    }

    await macroDoc.execute();
    ================================

	Reset/reshuffle a RollTable by name, or let the GM pick from world + compendiums.

	- Looks for exact name: "Hero Point Deck"
	- If not found, shows a dropdown:
		(W) = World table
		(C) = Compendium table
*/

(async () => {
	const TARGET_NAME = "Hero Point Deck";

	// Optional: GM-only, since this affects shared table state.
	if (!game.user?.isGM) {
		ui.notifications.warn("Only the GM can reshuffle roll tables.");
		return;
	}

	async function getWorldTables() {
		return Array.from(game.tables ?? []).map(t => ({
			source: "W",
			label: `${t.name} (W)`,
			uuid: t.uuid, // e.g. "RollTable.abc123"
			name: t.name
		}));
	}

	async function getCompendiumTables() {
		const out = [];
		const packs = Array.from(game.packs ?? []).filter(p => p.documentName === "RollTable");

		for (const pack of packs) {
			let index;
			try {
				// v12/v13: this is the fast way to get names without loading every document
				index = await pack.getIndex({ fields: ["name"] });
			} catch (err) {
				console.warn(`Failed to index pack ${pack.collection}`, err);
				continue;
			}

			for (const row of index) {
				const uuid = `Compendium.${pack.collection}.${row._id}`;
				out.push({
					source: "C",
					label: `${row.name} (C)`,
					uuid,
					name: row.name,
					packLabel: pack.metadata?.label ?? pack.collection
				});
			}
		}

		return out;
	}

	async function findByExactName(name) {
		// World first
		const world = await getWorldTables();
		const worldHit = world.find(t => t.name === name);
		if (worldHit) return worldHit;

		// Then compendiums
		const comp = await getCompendiumTables();
		const compHit = comp.find(t => t.name === name);
		if (compHit) return compHit;

		return null;
	}

	async function promptPickTable() {
		const [world, comp] = await Promise.all([getWorldTables(), getCompendiumTables()]);
		const all = [...world, ...comp].sort((a, b) => a.label.localeCompare(b.label));

		if (!all.length) {
			ui.notifications.error("No RollTables found in the world or any RollTable compendiums.");
			return null;
		}

		const optionsHtml = all
			.map(t => `<option value="${t.uuid}">${foundry.utils.escapeHTML(t.label)}</option>`)
			.join("");

		return new Promise((resolve, reject) => {
			new foundry.applications.api.DialogV2({
				window: { title: "Select a RollTable to reshuffle" },
				content: `
					<form>
						<p style="margin: 0 0 0.5rem 0;">
							No table named <strong>${foundry.utils.escapeHTML(TARGET_NAME)}</strong> was found.
							Pick a RollTable to reshuffle:
						</p>
						<div style="display:flex; gap:0.5rem; align-items:center;">
							<label for="rtPick" style="white-space:nowrap;">RollTable</label>
							<select id="rtPick" name="rtPick" style="flex:1;">
								${optionsHtml}
							</select>
						</div>
					</form>
				`,
				buttons: [
					{
						action: "ok",
						label: "Use Selected Table",
						default: true,
						callback: (event, button) => {
							const uuid = button.form?.elements?.rtPick?.value;
							resolve(uuid || null);
						}
					},
					{
						action: "cancel",
						label: "Cancel",
						callback: () => reject(new Error("User cancelled"))
					}
				],
				rejectClose: true
			}).render({ force: true });
		});
	}

	// 1) Try exact-name auto-find
	let picked = await findByExactName(TARGET_NAME);

	// 2) If not found, prompt
	if (!picked) {
		let pickedUuid;
		try {
			pickedUuid = await promptPickTable();
		} catch {
			return; // cancelled
		}
		if (!pickedUuid) return;

		picked = { uuid: pickedUuid };
	}

	// 3) Load and reset
	const table = await fromUuid(picked.uuid);
	if (!table) {
		ui.notifications.error(`Could not load RollTable: ${picked.uuid}`);
		return;
	}

	await table.resetResults();

	await ChatMessage.create({
		content: "<strong>Hero Cards Deck reshuffled!</strong>",
		speaker: { alias: "Game Master" }
	});
})();
